def check_solution(a):
    # k = (3048192 - 3818*a) / (8*a + 17946)
    numerator = 3048192 - 3818 * a
    denominator = 8 * a + 17946

    if denominator == 0:
        return None

    k = numerator / denominator

    if abs(k - round(k)) < 1e-9: # Check if k is essentially an integer
        k_int = int(round(k))
        b = 2 * k_int
        return (a, b)
    return None

solutions = []
# Test a broader range
for a_test in range(-1000, 1001):
    sol = check_solution(a_test)
    if sol:
        solutions.append(sol)

if solutions:
    print("Integer solutions found for (a, b) where b is even:")
    for s in solutions:
        print(s)
else:
    print("No integer solutions found in the tested range for a.")
